import numpy as np

class IndependentRipple:
    def __init__(self, dim=5):
        self.dim = dim
        # Unique base frequencies and amplitudes for each dimension
        self.base_freqs = 2 * np.pi * np.arange(1, dim + 1)
        self.amplitudes = np.exp(-0.5 * (np.arange(dim) / dim) ** 2)

    def f(self, x):
        # Ensure x is within bounds [-5, 5] per dimension
        x = np.clip(x, -5.0, 5.0)
        # Sum of independent sinusoidal terms for each dimension
        return np.sum(self.amplitudes * np.sin(self.base_freqs * x))
